import { useLayoutEffect } from 'react'

/**
 * The public site's look (Paul, 11 Nov 2026: "bring the whole website to
 * consistent branding and experience"): every page a visitor sees is the home
 * page's navy and violet. It puts .theme-navy on <html> (src/theme-dark.css,
 * generated by scripts/generate-theme-dark.py) for as long as the page is open.
 *
 * - `built: 'light'` for a page written with light colours (the partner
 *   pages, a blog article, privacy and terms, sign in): .theme-dark turns it
 *   over, onto navy.
 * - `built: 'dark'` for a page written dark by hand (Learning, the course
 *   pages, the blog list, the glimpses): only its near-black turns navy.
 */
export function useSiteTheme(built: 'light' | 'dark') {
  useLayoutEffect(() => {
    const html = document.documentElement
    const classes = built === 'light' ? ['theme-navy', 'theme-dark'] : ['theme-navy']
    html.classList.add(...classes)
    return () => html.classList.remove(...classes)
  }, [built])
}
